create or replace function catalog._product_unit_has_sales_transaction_usage(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid
)
returns boolean
language plpgsql
stable
security definer
set search_path = catalog, pg_temp
as $$
begin
  -- Don vi da dung trong dong don ban, dong doi/tra, hoac dong nhap dang mo (status = 'active').
  -- plpgsql: ten bang sales.* chi duoc kiem luc chay (schema sales tao o 20260830005, sau file nay).
  return exists (select 1 from sales.sales_order_lines l
                 where l.tenant_id = p_tenant_id and l.product_id = p_product_id
                   and l.product_unit_id = p_product_unit_id)
      or exists (select 1 from sales.return_exchange_lines l
                 where l.tenant_id = p_tenant_id and l.product_id = p_product_id
                   and l.product_unit_id = p_product_unit_id)
      or exists (select 1 from sales.sales_order_draft_lines l
                 join sales.sales_order_drafts d
                   on d.tenant_id = l.tenant_id and d.id = l.sales_order_draft_id
                 where l.tenant_id = p_tenant_id and l.product_id = p_product_id
                   and l.product_unit_id = p_product_unit_id and d.status = 'active');
end;
$$;

create or replace function catalog._product_conversion_unit_delete_blocked_reason(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid
)
returns text
language plpgsql
stable
security definer
set search_path = catalog, pg_temp
as $$
begin
  if catalog._product_unit_has_sales_transaction_usage(
    p_tenant_id,
    p_product_id,
    p_product_unit_id
  ) then
    return 'Đơn vị đã được dùng trong giao dịch. Hãy dùng "Tắt đơn vị" để bảo toàn lịch sử.';
  end if;

  if exists (
    select 1
    from catalog.product_unit_price_bands pb
    where pb.product_unit_id = p_product_unit_id
      and pb.product_id = p_product_id
      and pb.tenant_id = p_tenant_id
  ) then
    return 'Đơn vị đã có khung giá bán. Hãy dùng "Tắt đơn vị" để bảo toàn lịch sử.';
  end if;

  return null;
end;
$$;

create or replace function catalog.delete_product_conversion_unit(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid
)
returns void
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
  v_unit record;
  v_block_reason text;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_units') then
    raise exception 'permission denied: catalog.product.manage_units';
  end if;

  select *
  into v_unit
  from catalog.product_units pu
  where pu.id = p_product_unit_id
    and pu.product_id = p_product_id
    and pu.tenant_id = p_tenant_id;

  if v_unit.id is null then
    raise exception 'product unit not found';
  end if;
  if v_unit.is_base_unit then
    raise exception 'validation_exception: Base unit cannot be deleted here.';
  end if;

  v_block_reason := catalog._product_conversion_unit_delete_blocked_reason(
    p_tenant_id,
    p_product_id,
    p_product_unit_id
  );
  if v_block_reason is not null then
    raise exception 'product_conversion_unit_delete_blocked: %', v_block_reason;
  end if;

  delete from catalog.product_units
  where id = p_product_unit_id;

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'delete_product_conversion_unit',
    jsonb_build_object(
      'product_unit_id', p_product_unit_id,
      'unit_name', v_unit.unit_name,
      'conversion_rate_to_base', v_unit.conversion_rate_to_base
    ),
    v_actor_id
  );
end;
$$;

revoke all on function catalog._product_unit_has_sales_transaction_usage(uuid, uuid, uuid)
  from public, anon;
grant execute on function catalog._product_unit_has_sales_transaction_usage(uuid, uuid, uuid)
  to authenticated, service_role;

