grant execute on function catalog._product_conversion_unit_delete_blocked_reason(uuid, uuid, uuid)
  to authenticated, service_role;

revoke all on function catalog.delete_product_conversion_unit(uuid, uuid, uuid) from public, anon;
grant execute on function catalog.delete_product_conversion_unit(uuid, uuid, uuid) to authenticated, service_role;
